entries[213158] = { ["name"] = "Räuberischer Blutstarrer", ["text"] = "Wirken in 1.5 sek.\nRäuberischer Blutstarrer : Beschwören oder wieder freigeben\n\"Die schiere Menge an rohen roten Beeren, die diese Allesfresser verschlingen, verleiht ihnen ihre bemerkenswerte Augenfarbe.\"\nQuest:\nBlutstarrerwiedersehen" }
