entries[213161] = { ["name"] = "Schnell wie der fließende Strom", ["text"] = "Rang 1/ 1 Artefakt Boni\nBenötigt Fu Zan, Gefährte des Wanderers\nDas Aktivieren von 'Stärkendes Gebräu', 'Reinigendes Gebräu' oder 'Eisenhautgebräu' erhöht Eure Bewegungsgeschwindigkeit 15 Sek. lang um 6%. Dieser Effekt ist bis zu 5-mal stapelbar." }
entries[213162] = { ["name"] = "Alptraumstoß", ["text"] = "Wirken in 2 sek.\nFügt Gegnern innerhalb von 30 Metern vor Cenarius 18650 Schattenschaden zu und erhöht ihren durch 'Alptraumstoß' erlittenen Schaden für 45 Sek. um 100%.\n\nDieser Effekt ist stapelbar." }
entries[213163] = { ["name"] = "Schneefederreißer", ["text"] = "Wirken in 1.5 sek.\nSchneefederreißer : Beschwören oder wieder freigeben\n\"Diese Tiere können sich unter einer Nebelbank verstecken, bis sich die Beute nähert, und dann herausspringen und das Opfer mit einem einzigen Krallenhieb aufschlitzen.\"\nQuest:\nSchneefederwiedersehen" }
entries[213164] = { ["name"] = "Prächtiger Düsterschnabel", ["text"] = "Wirken in 1.5 sek.\nPrächtiger Düsterschnabel : Beschwören oder wieder freigeben\n\"Die schimmernde Haut dieser ebenso wilden wie koordiniert agierenden Bestien dient dazu, ihre Beute zu verwirren und orientierungslos zu machen.\"\nQuest:\nDüsterschnabelwiedersehen" }
entries[213165] = { ["name"] = "Viridianscharfkralle", ["text"] = "Wirken in 1.5 sek.\nViridianscharfkralle : Beschwören oder wieder freigeben\n\"Dank ihrer Tarnungsfähigkeiten können sie sich in magischen Wäldern, wie man sie beispielsweise auf den Verheerten Inseln findet, perfekt an die Umgebung anpassen.\"\nQuest:\nScharfkrallenwiedersehen" }
entries[213166] = { ["name"] = "Sengendes Brandmal", ["text"] = "100 Meter Reichweite\nSofort\nAluriel markiert zufällige Ziele mit 'Sengendes Brandmal'. Danach setzt sie ihre Rüstung in Brand und stürmt auf die betroffenen Ziele zu. Gegner in ihrer Bahn werden zurückgestoßen und beginnen zu brennen, wodurch sie 25288 Feuerschaden erleiden. Dieser Effekt ist stapelbar.\n\nWenn mit 'Sengendes Brandmal' belegte Spielercharaktere sterben, explodieren sie automatisch." }
