entries[213248] = { ["name"] = "Transmutieren: Erz zu Stoff", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nLeysteinerz (5), Teufelsschiefer (5)\nTransmutiert Erz der Verheerten Inseln zu Stoff.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nHaufen Seide\nWird beim Aufheben gebunden\n\"Ein Haufen Shal'doreiseide. Kann auch zähflüssiges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[213249] = { ["name"] = "Transmutieren: Stoff zu Häuten", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nShal'doreiseide (10)\nTransmutiert Stoff der Verheerten Inseln zu Häuten.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nHaufen Häute\nWird beim Aufheben gebunden\n\"Ein Haufen Steinbalgleder und Sturmschuppen. Kann auch zähflüssiges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[213250] = { ["name"] = "Transmutieren: Häute zu Erz", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nSteinbalgleder (5), Sturmschuppe (5)\nTransmutiert Häute der Verheerten Inseln zu Erz.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nHaufen Erz\nWird beim Aufheben gebunden\n\"Ein Haufen Leysteine und Teufelsschiefer. Kann auch zähflüssiges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[213251] = { ["name"] = "Transmutieren: Erz zu Kräutern", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nLeysteinerz (5), Teufelsschiefer (5)\nTransmutiert Erz der Verheerten Inseln zu Kräutern.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nKräuterhaufen\nWird beim Aufheben gebunden\n\"Ein Haufen Kräuter von den Verheerten Inseln. Kann auch schwarzes Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[213252] = { ["name"] = "Transmutieren: Stoff zu Kräutern", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nShal'doreiseide (10)\nTransmutiert Stoff der Verheerten Inseln zu Kräutern.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nKräuterhaufen\nWird beim Aufheben gebunden\n\"Ein Haufen Kräuter von den Verheerten Inseln. Kann auch schwarzes Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[213253] = { ["name"] = "Transmutieren: Häute zu Kräutern", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nSteinbalgleder (5), Sturmschuppe (5)\nTransmutiert Häute der Verheerten Inseln zu Kräutern.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nKräuterhaufen\nWird beim Aufheben gebunden\n\"Ein Haufen Kräuter von den Verheerten Inseln. Kann auch schwarzes Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[213254] = { ["name"] = "Transmutieren: Fisch zu Edelsteinen", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nVerfluchter Königinnenfisch (5), Mooskiemenbarsch (5), Hochberglachs (5), Sturmrochen (5), Runenschuppenkoi (5), Schwarzer Barrakuda (5)\nTransmutiert Fische der Verheerten Inseln zu Edelsteinen.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nHaufen Juwelen\nWird beim Aufheben gebunden\n\"Ein Haufen Edelsteine. Kann auch öliges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[213255] = { ["name"] = "Transmutieren: Fleisch zu Hosen", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nMagere Haxe (5), Fettiges Bärensteak (5), Große Wildrippchen (5), Leyblut (5), Wildvogelei (5)\nTransmutiert Fleisch der Verheerten Inseln zu Hosen.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nHaufen Hosen\nWird beim Aufheben gebunden\n\"Ein Haufen Hosen. Kann auch öliges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[213256] = { ["name"] = "Transmutieren: Fleisch zu Begleiter", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nFettiges Bärensteak (3), Intakte Kralle (20), Intakter Zahn (20), Zähflüssiges Transmutagen , Schwarzes Transmutagen , Öliges Transmutagen\nTransmutiert Fleisch der Verheerten Inseln zu einem Begleiter.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nPulsierender Sack\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagen (Realzeit)\n\"Eine zuckende Masse aus transmutiertem Fleisch.\"" }
entries[213257] = { ["name"] = "Transmutieren: Blut von Sargeras", ["text"] = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nSchwarzes Transmutagen (5), Zähflüssiges Transmutagen (4), Öliges Transmutagen (3)\nTransmutiert Transmutagene der Verheerten Inseln zu Blut von Sargeras.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nBlut von Sargeras\nWird beim Aufheben gebunden\nHandwerksmaterial" }
